def reverse_every_k_chars(s, k):
    result = []
    for i in range(0, len(s), k):
        block = s[i:i+k]
        result.append(block[::-1])
    return ''.join(result)

def rotate_string_right(s, n):
    if len(s) == 0:
        return s
    n = n % len(s)
    if n == 0:
        return s
    return s[-n:] + s[:-n]

def longest_alternating_substring_length(s):
    if not s:
        return 0
    max_len = 1
    current = 1
    for i in range(1, len(s)):
        if s[i] != s[i-1]:
            current += 1
        else:
            current = 1
        max_len = max(max_len, current)
    return max_len

def count_distinct_substrings_length_k(s, k):
    n = len(s)
    if k <= 0 or k > n:
        return 0
    substrs = set(s[i:i+k] for i in range(n - k + 1))
    return len(substrs)

def first_repeated_character(s):
    seen = set()
    for c in s:
        if c in seen:
            return c
        seen.add(c)
    return None

def count_character_pairs(s, pair):
    if len(s) < 2:
        return 0
    count = 0
    for i in range(len(s) - 1):
        if s[i:i+2] == pair:
            count += 1
    return count

def is_suffix_of_any(s, words):
    if not words:
        return False
    for w in words:
        if w.endswith(s):
            return True
    return False

def remove_first_and_last_occurrence(s, ch):
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    if first == last:
        return s[:first] + s[first+1:]
    result = []
    for i, c in enumerate(s):
        if i == first or i == last:
            continue
        result.append(c)
    return ''.join(result)

def remove_char_at_indices(s, indices):
    idx_set = set(i for i in indices if 0 <= i < len(s))
    return ''.join(c for i, c in enumerate(s) if i not in idx_set)

def index_of_nth_occurrence(s, ch, n):
    count = 0
    for i, c in enumerate(s):
        if c == ch:
            count += 1
            if count == n:
                return i
    return -1

def distance_between_occurrences(s, ch):
    positions = [i for i, c in enumerate(s) if c == ch]
    return [positions[i+1] - positions[i] for i in range(len(positions) - 1)]

def is_every_other_char_same(s):
    n = len(s)
    for i in range(n - 2):
        if s[i] != s[i+2]:
            return False
    return True

def truncate_with_ellipsis(s, max_len):
    if len(s) > max_len:
        return s[:max_len - 3] + '...'
    return s

def is_kebab_case(s):
    if not s:
        return False
    segments = s.split('-')
    for seg in segments:
        if not seg:
            return False
        for c in seg:
            if not (c.isdigit() or (c.isalpha() and c.islower())):
                return False
    return True

def is_snake_case(s):
    if not s:
        return False
    segments = s.split('_')
    for seg in segments:
        if not seg:
            return False
        for c in seg:
            if not (c.isdigit() or (c.isalpha() and c.islower())):
                return False
    return True

def to_snake_case(s):
    if not s:
        return s
    result = s[0].lower()
    for c in s[1:]:
        if c.isupper():
            result += '_' + c.lower()
        else:
            result += c.lower()
    return result
